def elsewhere():
    return sandbox()  # an empty folder outside $DOJO, so relative paths into $DOJO fail

@task("1 cat")
def _():
    s = secret("cat")
    r, _ = go(1, dojo({"home/hacker/flag": s + "\n"}))
    assert r.stdout.strip() == s, f"print the contents of ~/flag {show(r)}"

@task("2 cat an absolute path")
def _():
    s = secret("abs")
    root = dojo({"flag": s + "\n"})
    r, _ = go(2, root, cwd=elsewhere())
    assert r.stdout.strip() == s, f"print $DOJO/flag by its absolute path (the check runs this script from outside $DOJO) {show(r)}"

@task("3 more catting practice")
def _():
    s = secret("chase")
    r, _ = go(3, dojo({"opt/vault/a1/b2/c3/flag": s + "\n"}), cwd=elsewhere())
    assert r.stdout.strip() == s, f"print $DOJO/opt/vault/a1/b2/c3/flag by its absolute path {show(r)}"

@task("4 grep for a needle")
def _():
    s = secret("grep")
    data = [" ".join(RNG.choice(["sdr", "pi", "radio", "wave", "academy", "flag"]) for _ in range(5)) for _ in range(20000)]
    data.insert(RNG.randrange(20000), s)
    r, _ = go(4, dojo({"challenge/data.txt": "\n".join(data) + "\n"}))
    assert r.stdout.strip() == s, f"print only the line containing academy{{ {show(r)}"

@task("5 diff")
def _():
    s = secret("diff")
    dec = [secret("decoy") for _ in range(100)]
    both = dec[:]
    both.insert(RNG.randrange(100), s)
    r, _ = go(5, dojo({"challenge/decoys_only.txt": "\n".join(dec) + "\n",
                       "challenge/decoys_and_real.txt": "\n".join(both) + "\n"}))
    assert s in r.stdout, f"the extra line should be in diff's output {show(r)}"
    assert sum(d in r.stdout for d in dec) == 0, "print only the difference, not the decoys"

@task("6 ls")
def _():
    name = "run-" + word()
    r, _ = go(6, dojo({"challenge/" + name: ""}))
    assert name in r.stdout.split(), f"list $DOJO/challenge (it holds a file called {name}) {show(r)}"

@task("7 touch")
def _():
    root = dojo()
    r, _ = go(7, root)
    for f in ("pwn", "college"):
        p = root / "tmp" / f
        assert p.is_file(), f"$DOJO/tmp/{f} was not created {show(r)}"
        assert p.stat().st_size == 0, f"$DOJO/tmp/{f} should be empty"

@task("8 rm")
def _():
    root = dojo()
    r, _ = go(8, root)
    assert not (root / "home/hacker/delete_me").exists(), f"~/delete_me still exists {show(r)}"
    assert (root / "home/hacker/keep_me").exists(), "only delete ~/delete_me, keep ~/keep_me"

@task("9 mv")
def _():
    s = secret("mv")
    root = dojo({"flag": s + "\n"})
    r, _ = go(9, root)
    dst = root / "tmp/hack-the-planet"
    assert dst.is_file() and dst.read_text().strip() == s, f"$DOJO/tmp/hack-the-planet should contain the text that was in $DOJO/flag {show(r)}"
    assert not (root / "flag").exists(), "mv moves: $DOJO/flag should be gone"

@task("10 cp")
def _():
    s = secret("cp")
    root = dojo({"flag": s + "\n"})
    r, _ = go(10, root)
    dst = root / "tmp/hack-the-planet"
    assert dst.is_file() and dst.read_text().strip() == s, f"$DOJO/tmp/hack-the-planet should be a copy of $DOJO/flag {show(r)}"
    assert (root / "flag").exists(), "cp copies: $DOJO/flag must still exist"

