@task("13 mkdir")
def _():
    root = dojo()
    r, _ = go(13, root)
    assert (root / "tmp/pwn").is_dir(), f"$DOJO/tmp/pwn should be a directory {show(r)}"
    assert (root / "tmp/pwn/college").is_file(), "create the file $DOJO/tmp/pwn/college"

@task("14 find")
def _():
    extra = {}
    for _ in range(4):
        extra["/".join(word(4) for _ in range(RNG.randint(1, 4))) + "/flag"] = secret("find")
    root = dojo(extra)
    want = sorted(str(p) for p in root.rglob("flag") if p.is_file())
    r, _ = go(14, root)
    got = sorted(lines(r))
    assert got == want, f"expected the {len(want)} paths of files named flag under $DOJO, got {len(got)} lines {show(r)}"

@task("15 symbolic link")
def _():
    s = secret("ln")
    root = dojo({"flag": s + "\n"})
    r, _ = go(15, root)
    link = root / "home/hacker/not-the-flag"
    assert link.is_symlink(), f"~/not-the-flag should be a symbolic link {show(r)}"
    assert s in r.stdout, f"catflag did not print $DOJO/flag. Did you run it after you made the link? {show(r)}"

